import hashlib, hmac
from nearproof import Challenge, Prover, Verifier

key = b"\x01" * 32
ctx = b"\x02" * 32
opening = b"\x03" * 32
digest = hashlib.sha256(b"NPC1" + ctx + opening).digest()
p = Prover(key)

v = Verifier(key, replay_protection=True)
c = v.new_challenge(context=ctx, digest=digest)
resp = p.reveal(c, ctx, opening)
exp = hmac.new(key, b"NPR1" + digest + c.round_index.to_bytes(8, "big") + c.nonce, hashlib.sha256).digest()
assert resp == exp, "reveal mismatch"
m = v.verify(c, resp, 0.0)
print("verify ok, distance:", m.distance_meters)
try:
    v.verify(c, resp, 0.0); print("FAIL")
except ValueError as e: print("consumed:", e)

v2 = Verifier(key, replay_protection=True)
c2 = v2.new_challenge(context=ctx, digest=digest)
try:
    v2.verify(c2, p.reveal(c2, ctx, b"\x04"*32), 0.0, opening=b"\x04"*32); print("FAIL")
except ValueError as e: print("wrong opening:", e)
v2.verify(c2, p.reveal(c2, ctx, opening), 0.0, opening=opening)
print("retry ok")

v3 = Verifier(key, replay_protection=True)
c3 = v3.new_challenge(context=ctx, digest=digest)
try:
    v3.verify(c3, p.reveal(c3, ctx, opening), 0.0); print("FAIL")
except ValueError as e: print("no opening:", e)

v4 = Verifier(key, replay_protection=True)
c4 = v4.new_challenge()
try:
    v4.verify(c4, p.respond(c4), 0.0, opening=opening); print("FAIL")
except ValueError as e: print("unbound+opening:", e)

try:
    v4.new_challenge(context=ctx); print("FAIL")
except ValueError as e: print("pairing:", e)
try:
    Verifier(key).new_challenge(context=ctx, digest=digest); print("FAIL")
except ValueError as e: print("protection:", e)

legacy = Verifier(key)
ch = Challenge(1, b"0"*16)
try:
    legacy.verify(ch, p.respond(ch), 0.0, opening=opening); print("FAIL")
except ValueError as e: print("legacy+opening:", e)
legacy.verify(ch, p.respond(ch), 0.0)
print("legacy ok")

for bad in [True, -1, 1 << 64]:
    try:
        p.reveal(Challenge(bad, b"0"*16), ctx, opening); print("FAIL ri", bad)
    except ValueError: pass
try:
    p.reveal(Challenge(1, b"0"*15), ctx, opening); print("FAIL nonce")
except ValueError: pass
try:
    p.reveal("x", ctx, opening); print("FAIL type")
except TypeError: pass
try:
    p.reveal(Challenge(1, b"0"*16), ctx, b"\x03"*31); print("FAIL opening len")
except ValueError: pass
print("all smoke checks passed")
